f \text{ is differentiable at } a
  \;\Longleftrightarrow\;
\lim_{h \to 0} \frac{f(a + h) - f(a)}{h} \text{ exists}

f \text{ differentiable on } I
  \;\Longleftrightarrow\;
\forall a \in I,\; f'(a) \text{ exists}

\text{instantaneous rate of change}
  \;=\; \lim_{\Delta x \to 0} \frac{\Delta y}{\Delta x}
  \;=\; \lim_{x_2 \to x_1} \frac{f(x_2) - f(x_1)}{x_2 - x_1}

\begin{aligned}
  y = \sinh^{-1} x &\iff \sinh y = x,\\
  y = \cosh^{-1} x &\iff \cosh y = x \;\wedge\; y \ge 0,\\
  y = \tanh^{-1} x &\iff \tanh y = x.
\end{aligned}

\begin{aligned}
  \sinh(-x) &= -\sinh x, & \cosh(-x) &= \cosh x,\\
  \cosh^{2} x - \sinh^{2} x &= 1, & 1 - \tanh^{2} x &= \operatorname{sech}^{2} x,\\
  \sinh(x+y) &= \sinh x\cosh y + \cosh x\sinh y,\\
  \cosh(x+y) &= \cosh x\cosh y + \sinh x\sinh y.
\end{aligned}

F(x,y) = 0,\ y = y(x)\text{ derivable}
  \;\Longrightarrow\;
  \frac{dy}{dx}
    = -\,\frac{\partial F/\partial x}{\partial F/\partial y}
  \quad\text{(via chain rule on each term in }y\text{)}

f(x) = g(x) \;\text{para } x \neq a
\;\;\Longrightarrow\;\;
\lim_{x \to a} f(x) = \lim_{x \to a} g(x)

\lim_{x \to a} f(x) = L \iff
\lim_{x \to a^{-}} f(x) = L \;\;\text{y}\;\;
\lim_{x \to a^{+}} f(x) = L

\begin{aligned}
&\lim_{x\to a}\bigl[f(x)+g(x)\bigr]
  = \lim_{x\to a} f(x) + \lim_{x\to a} g(x), \\
&\lim_{x\to a}\bigl[f(x)-g(x)\bigr]
  = \lim_{x\to a} f(x) - \lim_{x\to a} g(x), \\
&\lim_{x\to a}\bigl[c\,f(x)\bigr] = c \lim_{x\to a} f(x), \\
&\lim_{x\to a}\bigl[f(x)\,g(x)\bigr]
  = \lim_{x\to a} f(x)\cdot \lim_{x\to a} g(x), \\
&\lim_{x\to a}\frac{f(x)}{g(x)}
  = \frac{\lim_{x\to a} f(x)}{\lim_{x\to a} g(x)}
  \quad \text{si } \lim_{x\to a} g(x) \neq 0.
\end{aligned}

f(x) \le g(x) \text{ cerca de } a
\;\;\Longrightarrow\;\;
\lim_{x \to a} f(x) \le \lim_{x \to a} g(x)

\text{Non-differentiability at } a:
\begin{cases}
  \text{(i) corner: }
    \lim_{h\to 0^{-}}\!\tfrac{f(a+h)-f(a)}{h}
    \neq
    \lim_{h\to 0^{+}}\!\tfrac{f(a+h)-f(a)}{h} \\
  \text{(ii) discontinuity: }
    \lim_{x\to a} f(x) \neq f(a)
    \text{ or undefined} \\
  \text{(iii) vertical tangent: }
    \lim_{x\to a}\bigl|f'(x)\bigr| = \infty
\end{cases}

F(x_1(t),\ldots,x_n(t)) = 0 \;\xrightarrow{\,d/dt\,}\;
\sum_{i=1}^{n}\frac{\partial F}{\partial x_i}\,\frac{dx_i}{dt} = 0
\;\Longrightarrow\; \frac{dx_k}{dt} = -\frac{1}{\partial F/\partial x_k}\sum_{i\neq k}\frac{\partial F}{\partial x_i}\,\frac{dx_i}{dt}

\begin{aligned}
&P \text{ polynomial} \implies P \text{ continuous on } \mathbb{R}, \\
&f = P/Q \text{ rational} \implies f \text{ continuous on its domain}.
\end{aligned}

\begin{aligned}
  \sinh^{-1} x &= \ln\!\bigl(x + \sqrt{x^{2} + 1}\bigr), & x &\in \mathbb{R},\\
  \cosh^{-1} x &= \ln\!\bigl(x + \sqrt{x^{2} - 1}\bigr), & x &\ge 1,\\
  \tanh^{-1} x &= \tfrac{1}{2}\ln\!\frac{1 + x}{1 - x}, & -1 &< x < 1.
\end{aligned}

f(x) \le g(x) \le h(x) \text{ cerca de } a
\;\;\text{y}\;\;
\lim_{x \to a} f(x) = \lim_{x \to a} h(x) = L
\;\;\Longrightarrow\;\;
\lim_{x \to a} g(x) = L
